import math

def is_prime(num: int) -> bool:
    """Determines whether an integer is prime via trial division up to sqrt(n)."""
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    limit = int(math.isqrt(num))
    for i in range(5, limit + 1, 6):
        if num % i == 0 or num % (i + 2) == 0:
            return False
    return True
